const fs = require('fs');
const vm = require('vm');
const assert = require('assert/strict');
const html = fs.readFileSync('index.html', 'utf8');
const script = html.match(/<script>([\\s\\S]*?)<\\/script>/)[1];
new vm.Script(script);
function setup(saved, blocked = false) {
  const ids = [...html.matchAll(/id=\"(["'^"]+)"/g)].map(m => m[1]);
  const elements = Object.fromEntries(ids.map(id => [id, { value: '"'', checked: false, hidden: false, disabled: false, textContent: '', listeners: {}, addEventListener(type, cb) {this.listeners[type] = cb;}, focus() {this.focused = true;}, setCustomValidity(text) {this.validation = text;}, reportValidity() {this.reported = true;} }]));
  elements['guest-count'].value = '1';
  elements['guest-fields'].querySelectorAll = () => [elements['guest-count'], elements.dietary];
  let stored = saved ? JSON.stringify(saved) : null;
  const localStorage = {getItem() {if(blocked) throw Error('blocked'); return stored;}, setItem(k, v) {if(blocked) throw Error('blocked'); stored = v;}};
  class FormData {get(key) {return key === 'name' ? elements['guest-name'].value : key === 'attendance' ? elements.attending.checked ? 'yes' : 'no' : key === 'guests' ? elements['guest-count'].value : elements.dietary.value;}}
  vm.runInNewContext(script, {document: {getElementById: id => elements[id]}, localStorage, FormData});
  return {e:elements, submit() {elements['rsvp-form'].listeners.submit({preventDefault(){}});}, stored: () => JSON.parse(stored)};
}
let t = setup();
t.e['guest-name'].value = ' Sam Example '; t.e.attending.checked = true; t.e['guest-count'].value = '3'; t.e.dietary.value = ' Vegetarian ';
t.submit();
assert.deepEqual(t.stored(), {name:'Sam Example',attendance:'yes',guests:3,dietary:'Vegetarian'});
assert.equal(t.e['rsvp-form'].hidden, true);
assert.match(t.e['confirmation-message'].textContent, /3 seats/);
t.e['edit-rsvp'].listeners.click();
assert.equal(t.e['rsvp-form'].hidden, false);
t.e.attending.checked = false; t.e.declining.checked = true; t.e['rsvp-form'].listeners.change();
assert.equal(t.e['guest-fields'].hidden, true);
assert.equal(t.e.dietary.disabled, true);
t.submit(); assert.equal(t.stored().guests, 0); assert.equal(t.stored().dietary, '');
t = setup({name:'Priya Example',attendance:'yes',guests:2,dietary:'No nuts'});
assert.equal(t.e['guest-name'].value, 'Priya Example'); assert.equal(t.e['guest-count'].value, '2');
t = setup(null, true); t.e['guest-name'].value = 'Alex'; t.e.attending.checked = true; t.submit();
assert.match(t.e['storage-note'].textContent, /could not be saved/);
t = setup(); t.e['guest-name'].value = '  '; t.submit(); assert.equal(t.e['guest-name'].reported, true);
console.log('Passed: script syntax, accepting, declining, guest counts, dietary details, editing, saved response restoration, unavailable storage, and blank-name validation.');
