from html.parser import HTMLParser
class Check(HTMLParser):
    def __init__(self):
        super().__init__(); self.ids=[]; self.labels=[]
    def handle_starttag(self, tag, attrs):
        a=dict(attrs)
        if 'id' in a: self.ids.append(a['id'])
        if tag=='label': self.labels.append(a.get('for'))
p=Check(); p.feed(open('index.html').read())
assert len(p.ids)==len(set(p.ids)), 'Duplicate IDs'
assert all(label in p.ids for label in p.labels), 'Unlinked labels'
print('Passed: unique element IDs and form label references.')
PY"

